import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第31章 圣诞","description":"","frontmatter":{},"headers":[],"relativePath":"第31章_圣诞.md","filePath":"第31章_圣诞.md"}'),r={name:"第31章_圣诞.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第31章-圣诞" tabindex="-1">第31章 圣诞 <a class="header-anchor" href="#第31章-圣诞" aria-label="Permalink to &quot;第31章 圣诞&quot;">​</a></h1><p>十二月二十四号，学校没放假。</p><p>那天下午下了点小雨，晚上停了。晚自习照上，教室里的灯全开着，前黑板右上角写着距离期末考还有二十一天。</p><p>我们班那天在排座位。期末考之前要换一次位置，老师说换个环境有好处。我换来换去换到了靠窗那一排，窗外是操场，能看见一部分跑道。</p><p>我看到那条跑道的时候想到了那天晚上。那条跑道我后来没再去过。</p><p>新课表贴在了后墙上。有人围过去看，看了都散了。我没挤过去，等空了才去看了一眼。</p><p>十点多下课，走廊上挤了一波人。我回宿舍的路上，手机震了一下。</p><p>她说：你到宿舍了吗。</p><p>我说：快了。</p><p>她说：到了告诉我。</p><p>我到了宿舍，把书包放下，跟她说我到了。</p><p>她说：你下楼一趟。</p><p>我说：现在？</p><p>她说：嗯。</p><p>我说：什么事。</p><p>她说：你下来就知道了。</p><p>我下去了。</p><p>宿舍楼下面有一盏灯，光是白的。她站在灯下面，背着一个书包，手里抱着一个东西。那东西用纸包着，不大，扁扁的。</p><p>我走过去。</p><p>她说，给你。</p><p>我说，什么。</p><p>她说，你自己看。</p><p>我接过来。纸是她的作业本的封皮，反着包的，用透明胶粘了两道，粘得不太整齐。</p><p>我说，现在能拆吗。</p><p>她说，不行。</p><p>我说，那什么时候拆。</p><p>她说，你回去拆。</p><p>我说，为什么。</p><p>她说，有人在看。</p><p>我顺着她的眼睛往宿舍楼上看。三楼的一个窗户后面有个人影，很快缩回去了。</p><p>她说，我走了。</p><p>我说，你等一下。</p><p>她说，干嘛。</p><p>我说，你有东西给我，我没东西给你。</p><p>她说，你不用给我。</p><p>我说，那不行。</p><p>她看了我一会儿，说，那你要给我什么。</p><p>我想了一下。我口袋里只有一支笔，一串钥匙，一张饭卡。宿舍里也没有什么东西能拿出来。</p><p>我说，我明天给你。</p><p>她说，明天就不算今天了。</p><p>我说，那我今天给你一句话。</p><p>她说，什么话。</p><p>我说，今天是平安夜。</p><p>她说，这算什么话。</p><p>我说，这是我今天能给的。</p><p>她站在那里，没有动。过了几秒，她说，那你说点别的。</p><p>我说，那我给你一样东西。</p><p>我从口袋里把钥匙摸出来。钥匙串上挂着一把小刀，是爷爷留下来的，刀身很小，还没我小指长，平时用来削铅笔。</p><p>我把小刀取下来，递给她。</p><p>她说，这是什么。</p><p>我说，一把刀。</p><p>她说，我又不用削铅笔。</p><p>我说，你可以当别的用。</p><p>她接过去，在手里翻了两下。她说，你这人给东西样子真的很奇怪。</p><p>我说，我只有这个。</p><p>她说，行吧。</p><p>她把刀收进了书包，拉链拉上。</p><p>她说，你这人真笨。</p><p>她说，行吧。</p><p>她走了。走到一半她回头说了一句。</p><p>她说，回去别忘了拆。</p><p>我拿着那个东西上了楼。</p><p>回宿舍我把纸拆开。里面是一张画。</p><p>画是用彩铅画的，一张图画纸，比A4的一半大一点。</p><p>纸的边角有一处被橡皮擦过，擦得毛毛的。右下角有一个签字，很小，写的是两个字母。</p><p>画上是两个人。站在一条路的中间，一左一右。两个人的手是牵着的，但画得很简单，就是两根线。路的两边画了一排树，树上没有叶子。</p><p>天空是灰蓝色的。画的右上角有一小块是亮的，像是太阳，又像是一个洞。</p><p>画的下面写了四个字。</p><p>「别弄丢了」</p><p>我把那张画看了很久。</p><p>宿舍里的人都在洗脸刷牙，有人问我看什么。我说没什么。</p><p>那天晚上我给她发消息。</p><p>我说，我拆了。</p><p>她说，怎么样。</p><p>我说，挺好。</p><p>她说，就挺好？</p><p>我说，画得很好。</p><p>她说，你懂个屁。</p><p>我说，那两个人在走路。</p><p>她说，嗯。</p><p>我说，手是牵着的。</p><p>她说，那是画错了。</p><p>我说，我看不像画错。</p><p>她那边停了一会儿。</p><p>她说，你这个人有时候很讨厌。</p><p>那天晚上我把那张画夹进了本子里。夹之前我想了一下，把本子翻到最前面，把那张画夹在了第一页。</p><p>夹的时候我发现，纸比本子大，两边各露出一截。我用剪刀剪了剪，剪得不太齐。</p><p>本子的第一页以前是空着的。后来那一页一直没写别的字。</p><p>第二年那本本子写满了，我换新的。换的时候我把那张画取出来，夹进新本子的第一页。</p><p>再后来它跟我搬了几次家。每一次收拾东西，我都会先看它一眼，确认它还在。</p><p>第二天早上我去文具店买了一张明信片，是在校门口那家小店买的，两块五，上面印着一个很难看的风景。</p><p>我在背面写了一行字。</p><p>写完之后我自己看了一遍，觉得不好。又划掉重写，还是不满意。</p><p>第三遍我写的是：画收到。画上那两个人在走路。</p><p>写完我想了想，把这句也划了。</p><p>最后写的是最短的一句：</p><p>「下次换我画」</p><p>我把明信片给了她。托班上一个认识她们班的人带过去的，说是有人让转交。那个人问我是谁，我说不认识。</p><p>中午她发消息说：收到了。</p><p>我说：那个明信片是我挑的。</p><p>她说：我知道，字太丑了。</p><p>我说：我写了三遍。</p><p>她说：那还是丑。</p><p>她过了两分钟，又发来一条。</p><p>她说：我收着了。</p><p>我问：那把刀呢。</p><p>她说：什么刀。</p><p>我说：昨天那把。</p><p>她说：哦，在我书包里。</p><p>我说：你用了吗。</p><p>她说：削了两次铅笔。</p><p>我说：你不是不削铅笔吗。</p><p>她说：我现在削了。</p><p>那天下午我把那张明信片的事写在本子上。写完我数了一下，我手里她的东西，已经有四样了。</p><p>一张卡，夹在练习册里。一个瓶盖，在抽屉里。一张包装纸，夹在本子里。今天又多了一张画，夹在本子第一页。</p><p>都不值钱。加起来不到十块。</p><p>可我知道，我这一辈子可能就攒这么点东西了。</p><p>那天晚上宿舍里都没睡，几个人在床下铺了一张报纸，把白天买的东西摆开，有花生，有肉干，有一瓶水。我也凑过去坐了一会儿。</p><p>有人问我，你昨天是不是下楼了。</p><p>我说，嗯。</p><p>他说，你干嘛去了。</p><p>我说，取东西。</p><p>他说，谁给你送的。</p><p>我说，同学。</p><p>他没再问。他给我倒了半杯热水，杯子是共用的，我喝了一口就放下了。</p><p>那杯水是温的。</p><p>那天我在心里想了一件事：这个宿舍里没有一个人知道我床头那本本子里夹着什么。他们只知道我天天抱着个手机，晚上不睡。</p><p>这大概就是那时候我的全部日子。</p>',128)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
